verify:
choices = {o: choices[n] for o, n in {'C': 'A', 'A': 'B', 'D': 'C', 'B': 'D'}.items()}; answer = {'A': 'C', 'B': 'A', 'C': 'D', 'D': 'B'}[answer]  # shuffled: original letters
def pair(s):
    a, b = s.replace('\\(', '').replace('\\)', '').strip('() ').split(',')
    return (value(a), value(b))
x, y = symbols('x y')
sols = {(s[x], s[y]) for s in solve([Eq(x**2 + y**2, 25), Eq(y, x + 1)], [x, y], dict=True)}
assert sols == {(3, 4), (-4, -3)}
assert pair(choices[answer]) in sols
assert all(pair(choices[k]) not in sols for k in choices if k != answer)
